    ///     {
    ///         "checkout",
    ///         "inventory",
    ///         "payments",
    ///     };
    ///     var runbooks = new List&lt;NewRelic.Notebook&gt;();
    ///     foreach (var range in services.Select((v, k) =&gt; new { Key = k, Value = v }))
    ///     {
    ///         runbooks.Add(new NewRelic.Notebook($"runbooks-{range.Key}", new()
    ///         {
    ///             Title = $"{range.Value} - Runbook",
    ///             Content = JsonSerializer.Serialize(new Dictionary&lt;string, object?&gt;
    ///             {
    ///                 ["type"] = "declarative",
    ///                 ["version"] = 1,
    ///                 ["content"] = new[]
    ///                 {
    ///                     new Dictionary&lt;string, object?&gt;
    ///                     {
    ///                         ["type"] = "container",
    ///                         ["props"] = new Dictionary&lt;string, object?&gt;
    ///                         {
    ///                             ["layout"] = "stack",
    ///                         },
    ///                         ["content"] = new[]
    ///                         {
    ///                             new Dictionary&lt;string, object?&gt;
    ///                             {
    ///                                 ["type"] = "widget",
    ///                                 ["content"] = new Dictionary&lt;string, object?&gt;
    ///                                 {
    ///                                     ["type"] = "visualization",
    ///                                     ["id"] = "viz.markdown",
    ///                                     ["props"] = new Dictionary&lt;string, object?&gt;
    ///                                     {
    ///                                         ["text"] = @$"# {range.Value}
    /// 
    /// Add investigation steps and runbook content here.",
    ///                                     },
    ///                                 },
    ///                             },
    ///                             new Dictionary&lt;string, object?&gt;
    ///                             {
    ///                                 ["type"] = "widget",
    ///                                 ["props"] = new Dictionary&lt;string, object?&gt;
    ///                                 {
    ///                                     ["title"] = "Error rate",
    ///                                 },
    ///                                 ["content"] = new Dictionary&lt;string, object?&gt;
    ///                                 {
    ///                                     ["type"] = "visualization",
    ///                                     ["id"] = "viz.billboard",
    ///                                     ["props"] = new Dictionary&lt;string, object?&gt;
    ///                                     {
    ///                                         ["nrqlQueries"] = new[]
    ///                                         {
    ///                                             new Dictionary&lt;string, object?&gt;
    ///                                             {
    ///                                                 ["accountIds"] = new[]
    ///                                                 {
