    ///                                                 },
    ///                                                 ["query"] = $"SELECT percentage(count(*), WHERE error IS true) AS 'Error %' FROM Transaction WHERE appName = '{range.Value}' SINCE 1 hour ago",
    ///                                             },
    ///                                         },
    ///                                     },
    ///                                 },
    ///                             },
    ///                         },
    ///                     },
    ///                 },
    ///             }),
    ///         }));
    ///     }
    /// });
